draw:
var TH = p.TH, TC = p.TC, n = p.n;
var R = 8.31, L2 = Math.log(2);
var Wh = n * R * TH * L2, Wc = n * R * TC * L2, Wnet = Wh - Wc;
var e = 1 - TC / TH; if (e < 0) e = 0;

// units: V from V0 to 2V0, P = nRT/V with V0 = 1
var pad = 40;
var Pmax = n * R * TH * 1.15, Vmax = 2.35;
var X = function (v) { return pad + ((v - 0.65) / (Vmax - 0.65)) * (W - pad - 16); };
var Y = function (pp) { return H - pad + 6 - (pp / Pmax) * (H - pad); };

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.strokeStyle = C.rule; ctx.lineWidth = 1.2;
ctx.beginPath();
ctx.moveTo(pad, 8); ctx.lineTo(pad, Y(0)); ctx.lineTo(W - 8, Y(0));
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "left"; ctx.fillText("P", pad - 26, 16);
ctx.textAlign = "right"; ctx.fillText("V", W - 8, Y(0) + 16);

function iso(T, va, vb, put) {
  var N = 40;
  for (var i = 0; i <= N; i++) {
    var v = va + (vb - va) * i / N;
    put(X(v), Y(n * R * T / v), i === 0);
  }
}

ctx.fillStyle = C.faint; ctx.globalAlpha = 0.6;
ctx.beginPath();
iso(TH, 1, 2, function (x, y, f) { f ? ctx.moveTo(x, y) : ctx.lineTo(x, y); });
iso(TC, 2, 1, function (x, y) { ctx.lineTo(x, y); });
ctx.closePath(); ctx.fill();
ctx.globalAlpha = 1;

ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath();
iso(TH, 1, 2, function (x, y, f) { f ? ctx.moveTo(x, y) : ctx.lineTo(x, y); });
iso(TC, 2, 1, function (x, y) { ctx.lineTo(x, y); });
ctx.closePath(); ctx.stroke();

// corner dots
ctx.fillStyle = C.accent;
var pts = [[1, TH], [2, TH], [2, TC], [1, TC]];
for (var i = 0; i < 4; i++) {
  ctx.beginPath(); ctx.arc(X(pts[i][0]), Y(n * R * pts[i][1] / pts[i][0]), 3.5, 0, Math.PI * 2); ctx.fill();
}

ctx.fillStyle = C.figure;
ctx.textAlign = "center";
ctx.fillText("expand hot at " + TH.toFixed(0) + " K", (X(1) + X(2)) / 2, Y(n * R * TH / 1.35) - 8);
ctx.fillText("compress cold at " + TC.toFixed(0) + " K", (X(1) + X(2)) / 2, Y(n * R * TC / 1.4) + 20);
ctx.textAlign = "right";
ctx.fillText("cool, V fixed", X(2) - 6, (Y(n * R * TH / 2) + Y(n * R * TC / 2)) / 2);
ctx.textAlign = "left";
ctx.fillText("reheat, V fixed", X(1) + 6, (Y(n * R * TH) + Y(n * R * TC)) / 2);

ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("V_0", X(1) - 8, Y(0) + 16);
ctx.fillText("2V_0", X(2) - 10, Y(0) + 16);

out.note = "hot leg gives out " + Wh.toFixed(0) + " J, cold leg costs " + Wc.toFixed(0) +
  " J, net work " + Wnet.toFixed(0) + " J per cycle; with a perfect regenerator the efficiency is " +
  (e * 100).toFixed(1) + "%";
